def transform(grid):
    h, w = len(grid), len(grid[0])
    from collections import Counter
    background = Counter(v for row in grid for v in row).most_common(1)[0][0]
    out = [row[:] for row in grid]

    # A diagonal pair marks a line; extend it in both directions.
    for r in range(h - 1):
        for c in range(w):
            for dc in (-1, 1):
                nc = c + dc
                if 0 <= nc < w and grid[r][c] != background and grid[r][c] == grid[r + 1][nc]:
                    color = grid[r][c]
                    for sr, sc, dr, dd in ((r, c, -1, -dc), (r + 1, nc, 1, dc)):
                        rr, cc = sr + dr, sc + dd
                        while 0 <= rr < h and 0 <= cc < w and grid[rr][cc] == background:
                            out[rr][cc] = color
                            rr += dr
                            cc += dd
    return out
